return [
  { json: { hoja: 'Turnos Sellado', area: 'Sellado' } },
  { json: { hoja: 'Turnos Extrusión', area: 'Extrusión' } },
  { json: { hoja: 'Turnos Impresión', area: 'Impresión' } }
];

// Obtener el nombre del área desde el elemento actual del bucle
const area = $('Por cada área').item.json.area;

// Construir un array de filas con las 5 columnas reales
const rows = $input.all().map(item => {
  const obj = item.json;
  return [
    obj["OT's a Realizar"] || '',
    obj.col_2 || '',
    obj.col_3 || '',
    obj.col_4 || '',
    obj.col_5 || ''
  ];
});

function getCell(row, colIndex) {
  return row[colIndex] ? row[colIndex].toString().trim() : '';
}

const data = {
  area: area,
  ots: [],
  estado_maquinas: [],
  maquinas_habilitadas: [],
  maquinas_no_habilitadas: [],
  actividad_operarios: [],
  actividades_supervisores: [],
  novedades: [],
  prioridades_generales: ''
};

let currentSection = '';

for (let i = 0; i < rows.length; i++) {
  const row = rows[i];
  const a = getCell(row, 0);
  const b = getCell(row, 1);
  const c = getCell(row, 2);
  const d = getCell(row, 3);
  const e = getCell(row, 4);

  // Detectar secciones por el texto en la columna A
  if (a === 'Estado de las maquinas') {
    currentSection = 'estado_maquinas';
    i++; // saltar encabezados
    continue;
  }
  if (a === 'Maquinas Habilitadas') {
    currentSection = 'maquinas_habilitadas';
    i++;
    continue;
  }
  if (a === 'Maquinas No Habilitadas') {
    currentSection = 'maquinas_no_habilitadas';
    i++;
    continue;
  }
  if (a === 'Actividad de los operarios') {
    currentSection = 'actividad_operarios';
    i++;
    continue;
  }
  if (a === 'Actividad de los Supervisores') {
    currentSection = 'actividades_supervisores';
    i++;
    continue;
  }
  if (a === 'Observaciones Adicionales') {
    currentSection = 'novedades';
    i++; // saltar la fila de "Fecha y Hora | Novedad"
    continue;
  }

  // Procesar filas según la sección actual
  if (currentSection === 'estado_maquinas') {
    // A = número de máquina, B = ¿trabaja?, C = estado, D = trabajo pendiente
    if (a && !isNaN(a)) {
      data.estado_maquinas.push({
        maquina: a,
        trabaja: b,
        estado: c,
        pendiente: d
      });
    }
  } else if (currentSection === 'maquinas_habilitadas') {
    if (a && !isNaN(a)) {
      data.maquinas_habilitadas.push({
        maquina: a,
        operario: b,
        tarea: c,
        inicio: d,
        final_estimado: e
      });
    }
  } else if (currentSection === 'maquinas_no_habilitadas') {
    if (a && !isNaN(a)) {
      data.maquinas_no_habilitadas.push({
        maquina: a,
        motivo: b,
        reportada: c,
        tiempo_estimado: d,
        observaciones: e
      });
    }
  } else if (currentSection === 'actividad_operarios') {
    if (a && isNaN(a)) {
      data.actividad_operarios.push({
        nombre: a,
        maquina_area: b,
        actividad_asignada: c,
        ot_relacionada: d,
        observaciones: e
      });
    }
  } else if (currentSection === 'actividades_supervisores') {
    if (a && isNaN(a)) {
      data.actividades_supervisores.push({
        nombre: a,
        maquina_area: b,
        actividad: c,
        estado: d,
        observaciones: e
      });
    }
  } else if (currentSection === 'novedades') {
    // A = fecha/hora, B = novedad
    if (a || b) {
      data.novedades.push({
        fecha_hora: a,
        novedad: b
      });
    }
  }
}

return [{ json: data }];
